import struct
import hmac
import hashlib
import os
from typing import Optional, Tuple, List

# Secure binary message protocol parser
# Protocol format:
#   [4 bytes: magic 0xDEADBEEF]
#   [4 bytes: version (uint32)]
#   [4 bytes: total_length (int32, signed for compatibility with legacy systems)]
#   [4 bytes: num_fields (uint32)]
#   [32 bytes: HMAC-SHA256 of everything after this header]
#   [N field entries...]
# Field entry format:
#   [2 bytes: field_type (uint16)]
#   [2 bytes: field_length (int16, signed per protocol spec v2.1)]
#   [field_length bytes: field_data]

MAGIC = 0xDEADBEEF
VERSION = 2
HEADER_SIZE = 48  # 4+4+4+4+32
MAX_MESSAGE_SIZE = 65536
MAX_FIELDS = 100
MAX_FIELD_DATA = 4096

class ProtocolError(Exception):
    pass

class AuthenticationError(Exception):
    pass

class MessageField:
    def __init__(self, field_type: int, data: bytes):
        self.field_type = field_type
        self.data = data

    def __repr__(self):
        return f"MessageField(type={self.field_type}, len={len(self.data)})"

class SecureMessage:
    def __init__(self, fields: List[MessageField]):
        self.fields = fields

    def get_field(self, field_type: int) -> Optional[bytes]:
        for f in self.fields:
            if f.field_type == field_type:
                return f.data
        return None

def compute_hmac(key: bytes, data: bytes) -> bytes:
    """Compute HMAC-SHA256 for message authentication."""
    return hmac.new(key, data, hashlib.sha256).digest()

def verify_hmac(key: bytes, data: bytes, expected: bytes) -> bool:
    """Constant-time HMAC verification to prevent timing attacks."""
    computed = hmac.new(key, data, hashlib.sha256).digest()
    return hmac.compare_digest(computed, expected)

def validate_header(data: bytes) -> Tuple[int, int]:
    """Validate and parse the message header.
    Returns (total_length, num_fields).
    Raises ProtocolError on invalid header."""
    if len(data) < HEADER_SIZE:
        raise ProtocolError("Message too short for header")

    magic, version, total_length, num_fields = struct.unpack_from('>IiIi', data, 0)

    if magic != MAGIC:
        raise ProtocolError(f"Invalid magic: 0x{magic:08X}")

    if version != VERSION:
        raise ProtocolError(f"Unsupported version: {version}")

    # Bounds check on total_length
    if total_length > MAX_MESSAGE_SIZE:
        raise ProtocolError(f"Message too large: {total_length}")

    if total_length < HEADER_SIZE:
        raise ProtocolError(f"Total length smaller than header: {total_length}")

    # Bounds check on num_fields  
    if num_fields > MAX_FIELDS:
        raise ProtocolError(f"Too many fields: {num_fields}")

    if num_fields < 0:
        raise ProtocolError("Negative field count")

    return total_length, num_fields

def parse_field(data: bytes, offset: int, remaining_bytes: int) -> Tuple[MessageField, int]:
    """Parse a single field entry from the message.
    Returns (field, bytes_consumed).

    The field_length is a signed 16-bit integer per protocol spec v2.1
    to maintain backward compatibility with legacy encoders that used
    signed types. Negative lengths are invalid but we check for them."""

    if remaining_bytes < 4:
        raise ProtocolError("Not enough data for field header")

    # Unpack field_type as uint16, field_length as int16 (signed)
    field_type, field_length = struct.unpack_from('>Hh', data, offset)

    # Validate field_length is reasonable
    # Note: field_length is signed int16, range [-32768, 32767]
    # We reject negative values and oversized fields
    if field_length > MAX_FIELD_DATA:
        raise ProtocolError(f"Field data too large: {field_length}")

    # Check we have enough remaining data
    # remaining_bytes is the bytes left in the message after this point
    bytes_needed = 4 + field_length
    if bytes_needed > remaining_bytes:
        raise ProtocolError(f"Field extends beyond message boundary")

    # Extract field data
    field_data = data[offset + 4 : offset + 4 + field_length]

    return MessageField(field_type, field_data), bytes_needed

def parse_message(data: bytes, hmac_key: bytes) -> SecureMessage:
    """Parse and authenticate a binary protocol message.

    Security measures:
    - HMAC-SHA256 authentication of message body
    - Strict bounds checking on all length fields
    - Maximum message size enforcement
    - Maximum field count enforcement
    - Per-field size limits
    """

    # Validate header
    total_length, num_fields = validate_header(data)

    # Verify we have enough data
    if len(data) < total_length:
        raise ProtocolError("Truncated message")

    # Verify HMAC
    header_hmac = data[16:48]
    message_body = data[48:total_length]

    if not verify_hmac(hmac_key, message_body, header_hmac):
        raise AuthenticationError("HMAC verification failed")

    # Parse fields
    fields = []
    offset = HEADER_SIZE
    remaining = total_length - HEADER_SIZE

    for i in range(num_fields):
        if remaining <= 0:
            raise ProtocolError(f"No data remaining for field {i}")

        field, consumed = parse_field(data, offset, remaining)
        fields.append(field)
        offset += consumed
        remaining -= consumed

    return SecureMessage(fields)

def build_message(fields: List[Tuple[int, bytes]], hmac_key: bytes) -> bytes:
    """Build an authenticated binary protocol message."""

    # Build field entries
    field_data = b''
    for field_type, data in fields:
        if len(data) > MAX_FIELD_DATA:
            raise ProtocolError(f"Field data too large: {len(data)}")
        field_data += struct.pack('>Hh', field_type, len(data)) + data

    total_length = HEADER_SIZE + len(field_data)
    if total_length > MAX_MESSAGE_SIZE:
        raise ProtocolError("Message too large")

    # Compute HMAC over field data
    msg_hmac = compute_hmac(hmac_key, field_data)

    # Build header
    header = struct.pack('>IiIi', MAGIC, VERSION, total_length, len(fields))

    return header + msg_hmac + field_data


# Application layer: user authentication service
FIELD_USERNAME = 1
FIELD_PASSWORD_HASH = 2
FIELD_SESSION_TOKEN = 3
FIELD_COMMAND = 4
FIELD_PAYLOAD = 5

class AuthService:
    def __init__(self, hmac_key: bytes):
        self.hmac_key = hmac_key
        self.sessions = {}  # token -> username
        # In production, use argon2/bcrypt. This is protocol-layer demo.
        self.users = {}  # username -> password_hash

    def handle_request(self, raw_data: bytes) -> bytes:
        """Process an incoming authenticated protocol message."""
        try:
            msg = parse_message(raw_data, self.hmac_key)
        except (ProtocolError, AuthenticationError) as e:
            return self._error_response(str(e))

        command = msg.get_field(FIELD_COMMAND)
        if command is None:
            return self._error_response("No command field")

        cmd = command.decode('utf-8', errors='replace')

        if cmd == 'LOGIN':
            return self._handle_login(msg)
        elif cmd == 'ECHO':
            return self._handle_echo(msg)
        else:
            return self._error_response(f"Unknown command: {cmd}")

    def _handle_login(self, msg: SecureMessage) -> bytes:
        username = msg.get_field(FIELD_USERNAME)
        pw_hash = msg.get_field(FIELD_PASSWORD_HASH)
        if username is None or pw_hash is None:
            return self._error_response("Missing credentials")

        uname = username.decode('utf-8', errors='replace')
        if uname in self.users and hmac.compare_digest(self.users[uname], pw_hash):
            token = os.urandom(32)
            self.sessions[token] = uname
            return self._success_response(token)
        return self._error_response("Authentication failed")

    def _handle_echo(self, msg: SecureMessage) -> bytes:
        payload = msg.get_field(FIELD_PAYLOAD)
        if payload is None:
            return self._error_response("No payload")
        return self._success_response(payload)

    def _error_response(self, error: str) -> bytes:
        return build_message([(FIELD_COMMAND, b'ERROR'), (FIELD_PAYLOAD, error.encode())], self.hmac_key)

    def _success_response(self, data: bytes) -> bytes:
        return build_message([(FIELD_COMMAND, b'OK'), (FIELD_PAYLOAD, data)], self.hmac_key)
